css:
.profile {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 32px;
  font-family: system-ui, sans-serif;
}

.avatar {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  background-color: #fdba74;
  font-size: 1.5rem;
  font-weight: 600;
}

.name {
  margin: 0 0 8px;
}

.tags {
  display: flex;
  gap: 8px;
}

.tag {
  padding: 2px 10px;
  color: #9a3412;
  font-size: 0.875rem;
}

