}

/* ---- Solution ---- */
.avatar {
  border-radius: 50%;
  box-shadow: 0 0 0 3px #ffffff, 0 0 0 6px #f97316;
}

.tag {
  border: 1px solid #f97316;
  border-radius: 999px;
  background-color: #fff7ed;
}
